function mapState(){return {samples:roadSamples,cities,position:state.mode==='park'?route.getPoint(.04):car.position,heading:car.rotation.y,destination:state.destination,parked:state.mode==='park'};}
function chooseDestination(name){state.destination=name;renderDestinations();drawScreen();}
function renderDestinations(){$('#destinations').replaceChildren();for(const city of cities){const b=document.createElement('button');b.textContent=city.name;b.className=state.destination===city.name?'selected':'';b.setAttribute('aria-label',city.name+" rotası");b.onclick=()=>chooseDestination(city.name);$('#destinations').append(b);}}
function drawNavigation(){drawWorldMap($('#navigationMap').getContext('2d'),{x:0,y:0,w:800,h:600},mapState());const target=cities.find(c=>c.name===state.destination);$('#navigationStatus').textContent=target?target.name+' · '+Math.round(Math.hypot(target.x-car.position.x,target.z-car.position.z))+' m':cities.map(c=>c.name).join(' · ');}

function screenClick(x,y){fx.unlock();fx.click();for(let h of [...screenHits].reverse())if(x>=h.x&&x<=h.x+h.w&&y>=h.y&&y<=h.y+h.h){h.fn(x,y);if(state.screen==='music')setDisplay('music');drawScreen();renderSettings();break;}}
