musicLibrary=new MusicLibrary({audio,input:$('#musicFile'),list:$('#trackList'),title:$('#trackName'),subtitle:$('#trackArtist'),notify:toast,onTrack:track=>{trackTitle=track?track.name.replace(/\.[^.]+$/,''):'';drawScreen();},onChange:tracks=>{drawScreen();}});
function playMusic(){musicLibrary.toggle();}audio.onplay=audio.onpause=()=>drawScreen();
audio.addEventListener('volumechange',()=>{soundLevels.music=Math.round(audio.volume*100);state.volume=soundLevels.music;saveSound();});

$('#previousTrack').onclick=()=>musicLibrary.next(-1);$('#nextTrack').onclick=()=>musicLibrary.next(1);
