function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2300);}
function toggle(k){state[k]=!state[k];if(k==='locked')fx.chime();if(k==='night')applyNight();drawScreen();renderSettings();}function applyNight(){scene.background.set(state.night?'#192d42':state.mode==='park'?'#cbd9e3':'#b9d2e3');scene.fog.color.copy(scene.background);hemi.intensity=state.night?.5:1.45;sun.intensity=state.night?.5:3.2;if(state.night)state.lights=true;}
function updateMaterials(){setLinerMode(state.view==='driver');paintMaterials.forEach(m=>m.color.set(colors[state.paint][1]));leatherMaterials.forEach(m=>m.color.set(state.interior?'#24292e':'#deded7'));modelRoot.traverse(o=>{if(o.isMesh&&o.material.name==='wheel')o.material.color.set(state.rims?'#29323d':'#858c93');});amb.color.set(state.ambient);renderMini();drawScreen();}
function label(t,v=''){return `<div class="label">${t}<span>${v}</span></div>`;}function toggleHTML(k,t){return `<div class="toggle-row"><span>${t}</span><button class="toggle ${state[k]?'on':''}" data-toggle="${k}" aria-label="${t}" aria-pressed="${state[k]}"></button></div>`;}
function renderSettings(){let html='';if(state.tab==='exterior'){html=label('Boya',colors[state.paint][0])+`<div class="swatches">${colors.map((p,i)=>`<button class="swatch ${state.paint===i?'selected':''}" style="--color:${p[1]}" data-paint="${i}" aria-label="${p[0]}"></button>`).join('')}</div>`+label('Jant kaplaması')+`<div class="options"><button class="${!state.rims?'selected':''}" data-rims="0">Gümüş</button><button class="${state.rims?'selected':''}" data-rims="1">Grafit</button></div>`+toggleHTML('lights','Farlar')+toggleHTML('night','Gece')+'<button class="action" id="goCabin">İç mekân</button>';}else if(state.tab==='interior'){html=label('Döşeme')+`<div class="options"><button data-interior="0" class="${!state.interior?'selected':''}">Siyah & beyaz</button><button data-interior="1" class="${state.interior?'selected':''}">Siyah</button></div>`+label('Ambiyans')+`<div class="swatches">${['#d9a66f','#8fbcda','#b2a0e3','#df8e9d','#b4d9c9'].map(c=>`<button aria-label="Ambiyans ${c}" class="swatch ${state.ambient===c?'selected':''}" style="--color:${c}" data-ambient="${c}"></button>`).join('')}</div>`+label('Koltuk konumu')+`<input class="range" aria-label="Koltuk konumu" type="range" min="-7" max="7" value="${state.seatPos}" data-range="seatPos">`+label('Bakış yüksekliği')+`<input class="range" aria-label="Bakış yüksekliği" type="range" min="-5" max="6" value="${eyeHeight}" data-range="eyeHeight">`+'<button class="action" id="openDisplay">Orta ekran</button>';}else if(state.tab==='vehicle'){html=toggleHTML('locked','Araç kilidi')+toggleHTML('climate','Klima')+label('Sıcaklık',state.temp+'°')+`<input class="range" aria-label="Sıcaklık" type="range" min="16" max="30" value="${state.temp}" data-range="temp">`+label('Koltuk ısıtma',String(state.seat))+`<input class="range" aria-label="Koltuk ısıtma" type="range" min="0" max="3" value="${state.seat}" data-range="seat">`+'<div class="row-buttons"><button id="openMusic">♫ Müzik</button><button id="soundHorn">Korna</button></div>';}else{html=label('Müzik',soundLevels.music+'%')+`<input class="range" aria-label="Müzik sesi" type="range" min="0" max="100" value="${soundLevels.music}" data-sound="music">`+label('Araç sesleri',soundLevels.vehicle+'%')+`<input class="range" aria-label="Araç sesleri" type="range" min="0" max="100" value="${soundLevels.vehicle}" data-sound="vehicle">`+label('Buton sesleri',soundLevels.buttons+'%')+`<input class="range" aria-label="Buton sesleri" type="range" min="0" max="100" value="${soundLevels.buttons}" data-sound="buttons"><button class="action" id="openMusic">Ses kitaplığı</button>`;}$('#settings').innerHTML=html;renderVehicleSettings();}
function drawVehicleStatus(){const c=$('#vehiclePreview').getContext('2d');c.clearRect(0,0,390,280);c.drawImage(miniImage,0,75,390,325,0,0,390,280);$('#vehicleSpeed').textContent=state.mode==='park'?'P':Math.round(Math.abs(state.speed)*3.6);$('#vehicleUnit').textContent=state.mode==='park'?'Park':'km/sa';$('#vehicleLock').textContent=state.locked?'Kilitli':'Kilit açık';$('#vehicleClimate').textContent=state.climate?state.temp+'° · AUTO':'Klima kapalı';}
function renderVehicleSettings(){const el=$('#vehicleSettings');if(!el)return;el.innerHTML=toggleHTML('locked','Araç kilidi')+toggleHTML('lights','Farlar')+toggleHTML('climate','Klima')+toggleHTML('night','Gece')+label('Sıcaklık',state.temp+'°')+`<input class="range" aria-label="Araç sıcaklığı" type="range" min="16" max="30" value="${state.temp}" data-range="temp">`+['music','vehicle','buttons'].map((k,i)=>label(['Müzik sesi','Araç sesleri','Buton sesleri'][i],soundLevels[k]+'%')+`<input class="range" aria-label="${['Müzik ses düzeyi','Araç ses düzeyi','Buton ses düzeyi'][i]}" type="range" min="0" max="100" value="${soundLevels[k]}" data-sound="${k}">`).join('');}
