function resizeScene(){const host=$('#scene'),width=host.clientWidth,height=host.clientHeight,ratio=Math.min(devicePixelRatio||1,1.7);if(!width||!height)return;if(width===viewportWidth&&height===viewportHeight&&ratio===viewportRatio)return;viewportWidth=width;viewportHeight=height;viewportRatio=ratio;renderer.setPixelRatio(ratio);renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix();}
