function setDisplay(mode){state.display=mode;if(mode==='music')state.screen='music';if(mode==='map')state.screen='map';$('#screenPane').hidden=mode!=='screen';$('#mediaControls').hidden=mode!=='music';$('#navigationPane').hidden=mode!=='map';$$('[data-display]').forEach(b=>b.classList.toggle('selected',b.dataset.display===mode));drawScreen();}
let tabletTransition;
function transitionTablet(opening){const tablet=$('#screenDock'),wasHidden=tablet.hidden;const start=wasHidden?{opacity:0,transform:'translate3d(0,72px,0) scale(.96)'}:{opacity:getComputedStyle(tablet).opacity,transform:getComputedStyle(tablet).transform};tabletTransition?.cancel();if(opening)tablet.hidden=false;tablet.inert=!opening;if(wasHidden&&!opening)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;tabletTransition=tablet.animate([start,opening?{opacity:1,transform:'translate3d(0,0,0) scale(1)'}:{opacity:0,transform:'translate3d(0,48px,0) scale(.97)'}],{duration:reduced?1:opening?520:250,easing:opening?'cubic-bezier(.16,1,.3,1)':'cubic-bezier(.4,0,1,1)',fill:'both'});const animation=tabletTransition;animation.onfinish=()=>{if(!opening)tablet.hidden=true;animation.cancel();if(tabletTransition===animation)tabletTransition=null;};}
