function recoverRoad(){if(state.mode==='park')return;renderPrevious=null;const pose=closestRoadPose(roadSamples,car.position.x,car.position.z);if(!pose)return;car.position.set(pose.x,.02,pose.z);car.rotation.set(0,pose.heading,0);dynamics.reset();worldPhysics.reset(.02);accumulator=0;state.speed=0;state.steer=0;state.mode='drive';garage.visible=false;landscape.visible=true;state.gear='D';yaw=0;pitch=0;keys={};cameraReady=false;$('#speedValue').textContent='0';toast('Yola döndün');drawScreen();}
$('#recoverRoad').onclick=recoverRoad;
function toggleInterface(){if(state.mode==='park')return;const hidden=document.body.classList.toggle('ui-hidden');$('#toggleInterface').setAttribute('aria-pressed',String(hidden));$('#toggleInterface').setAttribute('aria-label',hidden?'Arayüzü göster':'Arayüzü gizle');$('#toggleInterface').title=hidden?'Arayüzü göster · U':'Arayüzü gizle · U';if(hidden){closeScreen();$('#panel').classList.add('closed');}}
