function park(){renderPrevious=null;document.body.classList.remove('ui-hidden');$('#toggleInterface').setAttribute('aria-pressed','false');keys={};worldPhysics.reset(.02);dynamics.reset();accumulator=0;state.mode='park';state.transition=0;state.speed=0;state.steer=0;state.gear='P';car.position.set(0,0,0);car.rotation.y=0;garage.visible=true;landscape.visible=false;theta=-2.18;phi=1.14;radius=7.5;cameraReady=false;$('#drive').innerHTML='Sürüşe çık <span>↗</span>';$('#customize').classList.add('selected');document.body.classList.remove('driving');if(innerWidth>900)$('#panel').classList.remove('closed');applyNight();setView('orbit');}
