$('#drive').onclick=drive;$('#reset').onclick=park;$('#customize').onclick=()=>{if(state.mode!=='park')park();else $('#panel').classList.toggle('closed');};
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.tab){state.tab=d.tab;$$('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===state.tab));if(d.tab==='interior')setView('driver');renderSettings();$('#panel').classList.remove('closed');}if(d.paint!==undefined){state.paint=+d.paint;updateMaterials();renderSettings();}if(d.rims!==undefined){state.rims=+d.rims;updateMaterials();renderSettings();}if(d.interior!==undefined){state.interior=+d.interior;updateMaterials();renderSettings();}if(d.ambient){state.ambient=d.ambient;updateMaterials();renderSettings();}if(d.toggle)toggle(d.toggle);if(b.id==='goCabin'){state.tab='interior';$$('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab==='interior'));setView('driver');renderSettings();}if(b.id==='openDisplay')openScreen();if(b.id==='openMusic')openScreen('music');if(b.id==='soundHorn')horn();});
document.addEventListener('input',e=>{if(!e.target.closest('#settings,#vehicleSettings'))return;const soundKey=e.target.dataset.sound;if(soundKey){soundLevels[soundKey]=+e.target.value;if(soundKey==='music'){state.volume=soundLevels.music;audio.volume=state.volume/100;}fx.setLevels(soundLevels);saveSound();const span=e.target.previousElementSibling?.querySelector('span');if(span)span.textContent=soundLevels[soundKey]+'%';return;}const k=e.target.dataset.range;if(!k)return;if(k==='eyeHeight')eyeHeight=+e.target.value;else state[k]=+e.target.value;if(['temp','seat'].includes(k)){let span=e.target.previousElementSibling?.querySelector('span');if(span)span.textContent=k==='temp'?state.temp+'°':state.seat;}drawScreen();});
