document.addEventListener('pointerdown',()=>fx.unlock(),{capture:true});
document.addEventListener('click',e=>{if(e.target.closest('button'))fx.click();});
const ray=new T.Raycaster(),mouse=new T.Vector2();renderer.domElement.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,lx:e.clientX,ly:e.clientY,moved:false};renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.lx,dy=e.clientY-drag.ly;drag.lx=e.clientX;drag.ly=e.clientY;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>5)drag.moved=true;if(state.view==='orbit'){theta-=dx*.006;phi=T.MathUtils.clamp(phi-dy*.004,.3,1.53);}else{yaw=T.MathUtils.clamp(yaw-dx*.004,-1.45,1.45);pitch=T.MathUtils.clamp(pitch+dy*.003,-.55,.45);}});renderer.domElement.addEventListener('pointerup',e=>{if(drag&&!drag.moved){const r=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);screenMesh.updateWorldMatrix(true,false);const hits=ray.intersectObject(screenMesh);if(hits.length)openScreen();}drag=null;});renderer.domElement.addEventListener('pointercancel',()=>drag=null);renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();if(state.view==='orbit')radius=T.MathUtils.clamp(radius+e.deltaY*.006,3.4,state.mode==='park'?7.9:13);},{passive:false});
window.addEventListener('keydown',e=>{const typing=e.target.matches('textarea,input:not([type=range]):not([type=file])')||e.target.isContentEditable;if(typing||$('#credits').open)return;const k=drivingKey(e);if(e.target.matches('input[type=range]')&&k.startsWith('arrow'))return;fx.unlock();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)){if(state.mode!=='park')e.preventDefault();keys[k]=true;}if(e.repeat)return;if(k==='r'){e.preventDefault();recoverRoad();}if(k==='c'||k==='e')setView(state.view==='orbit'?'driver':'orbit');if(k==='l')toggle('lights');if(k==='h')horn();if(k==='u')toggleInterface();if(k==='escape'){closeScreen();$('#panel').classList.add('closed');}});window.addEventListener('keyup',e=>keys[drivingKey(e)]=false);window.addEventListener('blur',()=>keys={});
const headlights=[];for(let s of [-1,1]){let l=new T.SpotLight('#e4f3ff',0,45,.55,.5,1);l.position.set(s*.64,.66,-2.1);l.target.position.set(s*.9,0,-23);car.add(l,l.target);headlights.push(l);}
const contactMap=texCanvas(256,512,(c,w,h)=>{c.translate(w/2,h/2);c.scale(1,2);const g=c.createRadialGradient(0,0,10,0,0,w/2);g.addColorStop(0,'rgba(0,0,0,.5)');g.addColorStop(.6,'rgba(0,0,0,.25)');g.addColorStop(1,'rgba(0,0,0,0)');c.fillStyle=g;c.fillRect(-w/2,-h/4,w,h/2);});const contact=plane(2.6,5.0,0,.006,0,new T.MeshBasicMaterial({map:contactMap,transparent:true,depthWrite:false,opacity:.5}),car);contact.castShadow=false;
const chassis=new T.Group();car.add(chassis);for(const child of [...car.children])if(child!==chassis&&child!==contact){chassis.attach(child);child.position.y-=.64;}chassis.position.y=.64;
function updateCamera(dt){ceiling.visible=state.view==='driver';let pos=new T.Vector3(),target=new T.Vector3();if(state.view==='orbit'){let fit=radius;pos.set(Math.sin(theta)*Math.sin(phi)*fit,Math.cos(phi)*fit+.42,Math.cos(theta)*Math.sin(phi)*fit);target.set(innerWidth>1100?.35:0,.65,0);camera.fov=Math.max(43,2*Math.atan(Math.tan(T.MathUtils.degToRad(43)/2)/camera.aspect)*180/Math.PI);}else{pos.set(-.375,1.07+eyeHeight*.01,.12+state.seatPos*.01);target.copy(pos).add(new T.Vector3(Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch)).multiplyScalar(3));camera.fov=innerWidth<600?84:74;}
const up=new T.Vector3(0,1,0);camera.up.set(0,1,0);if(state.view==='driver'){pos.sub(chassis.position).applyQuaternion(chassis.quaternion).add(chassis.position);target.sub(chassis.position).applyQuaternion(chassis.quaternion).add(chassis.position);camera.up.applyQuaternion(chassis.quaternion).applyAxisAngle(up,car.rotation.y);}if(!cameraReady){camPos.copy(pos);camTarget.copy(target);cameraReady=true;}const smooth=state.view==='driver'?1:1-Math.exp(-dt*14);camPos.lerp(pos,smooth);camTarget.lerp(target,smooth);camera.position.copy(camPos).applyAxisAngle(up,car.rotation.y).add(car.position);const worldTarget=camTarget.clone().applyAxisAngle(up,car.rotation.y).add(car.position);camera.lookAt(worldTarget);camera.updateProjectionMatrix();}
function readRenderPose(){return {x:car.position.x,y:car.position.y,z:car.position.z,heading:car.rotation.y,pitch:state.mode==='drive'?worldPhysics.pitch:0,roll:state.mode==='drive'?worldPhysics.roll:0,steer:state.steer,steeringWheel:dynamics.steeringWheel,wheelTravel};}

function frame(t){requestAnimationFrame(frame);resizeScene();const elapsed=Math.min((t-last)/1000||1/60,.1);last=t;clock+=elapsed;accumulator+=elapsed;
while(accumulator>=1/120){renderPrevious=readRenderPose();const dt=1/120;const turn=steeringInput(keys);const braking=keys.s||keys.arrowdown||keys[' '];
if(state.mode==='exit'){state.transition+=dt;car.position.z-=3.5*dt;state.speed=3.5;if(state.transition>3.1){state.mode='drive';garage.visible=false;landscape.visible=true;const spawn=closestRoadPose(roadSamples,0,390);car.position.set(spawn.x,.02,spawn.z);car.rotation.y=spawn.heading;worldPhysics.reset(.02);dynamics.reset();state.speed=0;cameraReady=false;applyNight();}}
else {const distance=state.mode==='drive'?nearRoad(car.position.x,car.position.z):0;const grip=distance>8?.46:distance>5.7?.72:1;
dynamics.step(dt,{enabled:state.mode==='drive'&&!worldPhysics.flipped,steer:turn,throttle:!!(keys.w||keys.arrowup),brake:!!braking,handbrake:!!keys[' ']},{grip,grade:worldPhysics.grade,grounded:worldPhysics.grounded});state.steer=dynamics.steer;
if(state.mode==='drive'){const pose={x:car.position.x,z:car.position.z,heading:car.rotation.y};worldPhysics.step(dt,pose,dynamics);car.position.set(pose.x,worldPhysics.y,pose.z);car.rotation.y=pose.heading;
if(car.position.x< -30||car.position.x>690||Math.abs(car.position.z)>560){dynamics.speed*=-.12;dynamics.lateralSpeed=0;dynamics.yawRate*=.5;car.position.x=T.MathUtils.clamp(car.position.x,-29.9,689.9);car.position.z=T.MathUtils.clamp(car.position.z,-559.9,559.9);}}
state.speed=dynamics.speed;}wheelTravel+=state.speed*dt;accumulator-=dt;}
const dt=elapsed,physicalPose=readRenderPose(),renderPose=blendRenderPose(renderPrevious,physicalPose,accumulator*120);car.position.set(renderPose.x,renderPose.y,renderPose.z);car.rotation.y=renderPose.heading;chassis.rotation.set(renderPose.pitch,0,renderPose.roll);if(state.mode==='drive'&&worldPhysics.impact>3)fx.impact(worldPhysics.impact);chassis.position.y=.64;$('#speedValue').textContent=String(Math.round(Math.abs(state.speed)*3.6));
for(const [k,w]of Object.entries(wheelGroups)){w.roll.rotation.x=-renderPose.wheelTravel/.3451;if(k.startsWith('f')){const side=k==='fl'?-1:1;const steer=renderPose.steer,denom=2.875/Math.max(.001,Math.abs(Math.tan(steer)))+side*Math.sign(steer)*.81;w.steer.rotation.y=steer===0?0:Math.sign(steer)*Math.atan(2.875/Math.max(1.5,denom));}}
steeringPivot.quaternion.setFromAxisAngle(steeringAxis,renderPose.steeringWheel);
headlights.forEach(l=>l.intensity=state.lights?35:0);lightMaterials.forEach(({m,role})=>m.emissiveIntensity=role==='tail'?(dynamics.brake>.05||(!keys.w&&Math.abs(state.speed)>3)?3:state.lights?1.8:.35):(state.lights?4:1));
if(state.mode!=='park'){sun.position.copy(car.position).add(new T.Vector3(-12,18,-10));sun.target.position.copy(car.position);}else{sun.position.set(-12,16,-10);sun.target.position.set(0,0,0);}fx.update(dynamics,state.mode==='drive'||state.mode==='exit',state.view==='driver');updateCamera(dt);renderer.render(scene,camera);car.position.set(physicalPose.x,physicalPose.y,physicalPose.z);car.rotation.y=physicalPose.heading;if(t-screenTime>250){if(state.view==='driver'||!$('#screenDock').hidden){renderMini();drawScreen();}screenTime=t;}}
window.addEventListener('resize',resizeScene);resizeScene();renderDestinations();renderMini();drawScreen();renderSettings();if(innerWidth<900)$('#panel').classList.add('closed');$('#loading').remove();requestAnimationFrame(frame);

